use std::sync::{Arc, Mutex};

use axum::routing::get;
use axum::Router;

pub mod handlers;
pub mod repository;

#[derive(Clone)]
pub struct AppState {
    pub products: Arc<Mutex<repository::ProductRepository>>,
}

pub fn build_router() -> Router {
    let state = AppState {
        products: Arc::new(Mutex::new(repository::ProductRepository::new())),
    };
    Router::new()
        .route("/products", get(handlers::list_products))
        .with_state(state)
}

