use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use serde_json::Value;
use tower::ServiceExt;

async fn send(app: axum::Router, method: &str, uri: &str, body: Option<&str>) -> (StatusCode, Value) {
    let mut builder = Request::builder().method(method).uri(uri);
    let request = match body {
        Some(b) => builder
            .header("content-type", "application/json")
            .body(Body::from(b.to_string()))
            .unwrap(),
        None => builder.body(Body::empty()).unwrap(),
    };
    let res = app.oneshot(request).await.unwrap();
    let status = res.status();
    let bytes = to_bytes(res.into_body(), usize::MAX).await.unwrap();
    let value = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, value)
}

async fn ids(app: axum::Router, uri: &str) -> Vec<i64> {
    let (status, body) = send(app, "GET", uri, None).await;
    assert_eq!(status, StatusCode::OK, "{uri}: {body}");
    let mut out: Vec<i64> = body.as_array().unwrap().iter()
        .map(|p| p["id"].as_i64().unwrap()).collect();
    out.sort();
    out
}

#[tokio::test]
async fn product_filters() {
    let app = webapp::build_router();
    assert_eq!(ids(app.clone(), "/products").await, vec![1, 2, 3, 4]);
    assert_eq!(ids(app.clone(), "/products?category=garden").await, vec![3, 4]);
    assert_eq!(ids(app.clone(), "/products?maxPrice=25").await, vec![1, 2],
        "maxPrice must be INCLUSIVE (the 25-priced hammer stays)");
    assert_eq!(ids(app.clone(), "/products?category=garden&maxPrice=35").await, vec![4]);
    assert_eq!(ids(app, "/products?category=tools&maxPrice=15").await, vec![2]);
}

