use serde::Serialize;

#[derive(Clone, Serialize)]
pub struct Product {
    pub id: i64,
    pub name: String,
    pub category: String,
    pub price: i64,
}

pub struct ProductRepository {
    products: Vec<Product>,
}

impl ProductRepository {
    pub fn new() -> Self {
        ProductRepository {
            products: vec![
                Product { id: 1, name: "Steel Hammer".into(), category: "tools".into(), price: 25 },
                Product { id: 2, name: "Rubber Mallet".into(), category: "tools".into(), price: 15 },
                Product { id: 3, name: "Garden Hose".into(), category: "garden".into(), price: 40 },
                Product { id: 4, name: "Steel Rake".into(), category: "garden".into(), price: 30 },
            ],
        }
    }

    pub fn list(&self) -> Vec<Product> {
        self.products.clone()
    }
}

impl ProductRepository {
    pub fn search(&self, category: Option<&str>, max_price: Option<i64>) -> Vec<Product> {
        self.products
            .iter()
            .filter(|p| category.map_or(true, |c| p.category == c))
            .filter(|p| max_price.map_or(true, |m| p.price <= m))
            .cloned()
            .collect()
    }
}

